starterCode:
def parse_sort(value):
    # "-price" -> {"field": "price", "order": "desc"}; "price" -> {"field": "price", "order": "asc"}; пустое поле -> None
    pass

solution:
def parse_sort(value):
    order = "asc"
    if value.startswith("-"):
        order = "desc"
        value = value[1:]
    if not value:
        return None
    return {"field": value, "order": order}

